CREATE PROCEDURE [probe].[p_params]
    @id int,
    @name nvarchar(50) = N'none',
    @amount decimal(10, 2) = 1.5,
    @result int OUTPUT,
    @items [probe].[line_items] READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @result = @id;
END

